.chakra-orbit {
  transform-style: preserve-3d;
  animation: orbit-3d 44s linear infinite;
}
@keyframes orbit-3d {
  from {
    transform: rotateX(64deg) rotateZ(0deg);
  }
  to {
    transform: rotateX(64deg) rotateZ(360deg);
  }
}
.orbit-ring {
  position: absolute;
  border-radius: 9999px;
}
.orbit-ring.r1 {
  inset: 6%;
  border: 1.5px solid rgba(200, 100, 14, 0.30);
  transform: translateZ(46px);
}
.orbit-ring.r2 {
  inset: 16%;
  border: 1px dashed rgba(29, 58, 44, 0.32);
  transform: translateZ(96px);
}
.orbit-ring.r3 {
  inset: 26%;
  border: 1px solid rgba(200, 100, 14, 0.18);
  transform: translateZ(12px);
}
.orbit-ring.r4 {
  inset: 0;
  border: 1px solid rgba(28, 29, 24, 0.10);
  transform: translateZ(-48px);
}
@keyframes shake-x {
  0%, 100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-8px);
  }
  40% {
    transform: translateX(8px);
  }
  60% {
    transform: translateX(-5px);
  }
  80% {
    transform: translateX(5px);
  }
}
.animate-shake {
  animation: shake-x 0.45s ease-in-out;
}
@media (prefers-reduced-motion: reduce) {
  .chakra-orbit {
    animation: none;
  }
  .animate-shake {
    animation: none;
  }
}
